const saveTimers = new WeakMap();
const saveQueues = new WeakMap();

function errorMessage(html) {
  const document = new DOMParser().parseFromString(html, "text/html");
  const message =
    document.querySelector(".error") ||
    document.querySelector(".error-page p:last-of-type");
  return (message?.textContent || document.body.textContent || "Неизвестная ошибка").trim();
}

async function sendHx(form) {
  const url = form.getAttribute("hx-post");
  const target = document.querySelector(form.getAttribute("hx-target"));
  const swap = form.getAttribute("hx-swap");
  if (target && swap !== "outerHTML") target.textContent = "Сохраняется…";
  form.setAttribute("aria-busy", "true");

  try {
    const response = await fetch(url, {
      method: "POST",
      body: new FormData(form),
      credentials: "same-origin",
      headers: { "HX-Request": "true" },
    });
    const html = await response.text();
    if (!response.ok) throw new Error(errorMessage(html));
    if (target) {
      if (swap === "outerHTML") target.outerHTML = html;
      else target.innerHTML = html;
    }
    const included = form.elements.included;
    if (included) {
      form.closest(".review-card")?.classList.toggle("excluded", !included.checked);
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (target && swap !== "outerHTML") target.textContent = `Ошибка: ${message}`;
    else alert(`Не удалось выполнить действие: ${message}`);
  } finally {
    form.removeAttribute("aria-busy");
  }
}

function queueSave(form) {
  const previous = saveQueues.get(form) || Promise.resolve();
  const next = previous.then(() => sendHx(form));
  saveQueues.set(form, next);
  return next;
}

document.addEventListener("input", (event) => {
  const form = event.target.closest?.("form.card-editor");
  if (!form) return;
  clearTimeout(saveTimers.get(form));
  const target = document.querySelector(form.getAttribute("hx-target"));
  if (target) target.textContent = "Есть несохранённые изменения";
  saveTimers.set(
    form,
    setTimeout(() => {
      saveTimers.delete(form);
      queueSave(form);
    }, 700),
  );
});

document.addEventListener("change", (event) => {
  const form = event.target.closest?.("form.card-editor");
  if (!form) return;
  clearTimeout(saveTimers.get(form));
  saveTimers.delete(form);
  queueSave(form);
});

document.addEventListener("submit", async (event) => {
  const form = event.target;
  if (!form.getAttribute("hx-post")) return;
  event.preventDefault();
  if (form.classList.contains("card-editor")) {
    clearTimeout(saveTimers.get(form));
    saveTimers.delete(form);
    await queueSave(form);
    return;
  }
  const editor = form.closest(".review-card")?.querySelector("form.card-editor");
  if (editor && saveTimers.has(editor)) {
    clearTimeout(saveTimers.get(editor));
    saveTimers.delete(editor);
    await queueSave(editor);
  }
  await sendHx(form);
});
